package pe.com.dentalamericana.treatment;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;
@Entity @Table(name="planes_tratamiento")public class TreatmentPlan{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="paciente_id",nullable=false)private Long patientId;@Column(name="atencion_id")private Long encounterId;@Column(nullable=false,unique=true)private String codigo;@Enumerated(EnumType.STRING)@Column(nullable=false)private TreatmentPlanStatus estado;@Column(nullable=false)private BigDecimal descuento=BigDecimal.ZERO;@Column(nullable=false)private BigDecimal subtotal=BigDecimal.ZERO;@Column(nullable=false)private BigDecimal total=BigDecimal.ZERO;@Column(length=1000)private String observaciones;@Column(name="aceptado_por_paciente",nullable=false)private boolean patientAccepted;@Column(name="aceptado_en")private Instant acceptedAt;@Column(name="creado_por",nullable=false)private Long createdBy;@Column(name="actualizado_por",nullable=false)private Long updatedBy;@Column(name="creado_en",nullable=false)private Instant createdAt;@Column(name="actualizado_en",nullable=false)private Instant updatedAt;@Version private Long version;protected TreatmentPlan(){}public TreatmentPlan(Long patientId,Long encounterId,String code,String observations,Long actor){this.patientId=patientId;this.encounterId=encounterId;this.codigo=code;this.observaciones=observations;this.estado=TreatmentPlanStatus.BORRADOR;this.createdBy=actor;this.updatedBy=actor;}public void recalculate(BigDecimal subtotal,BigDecimal discount,Long actor){this.subtotal=subtotal;this.descuento=discount.min(subtotal);this.total=subtotal.subtract(this.descuento);this.updatedBy=actor;}public void revise(BigDecimal discount,String observations,Long actor){this.observaciones=observations;recalculate(this.subtotal,discount,actor);}public void changeStatus(TreatmentPlanStatus status,boolean accepted,Long actor){this.estado=status;this.patientAccepted=accepted;if(accepted)this.acceptedAt=Instant.now();this.updatedBy=actor;}@PrePersist void create(){Instant n=Instant.now();createdAt=n;updatedAt=n;}@PreUpdate void update(){updatedAt=Instant.now();}public Long getId(){return id;}public Long getPatientId(){return patientId;}public Long getEncounterId(){return encounterId;}public String getCode(){return codigo;}public TreatmentPlanStatus getStatus(){return estado;}public BigDecimal getDiscount(){return descuento;}public BigDecimal getSubtotal(){return subtotal;}public BigDecimal getTotal(){return total;}public String getObservations(){return observaciones;}public boolean isPatientAccepted(){return patientAccepted;}public Instant getAcceptedAt(){return acceptedAt;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}public Long getVersion(){return version;}}
